class Animal {
    String name;

    Animal(String name) {
        this.name = name;
    }

    void speak() {
        System.out.println(name + " makes a sound");
    }
}

class Dog extends Animal {
    String breed;

    Dog(String name, String breed) {
        super(name);  // 부모 생성자 호출
        this.breed = breed;
    }

    void speak() {
        super.speak();  // 부모 메서드 호출
        System.out.println(name + " barks!");
    }
}

Dog dog = new Dog("Max", "Labrador");
